cd /testbed && python3 - <<'PY'
import subprocess, time
servers = []
try:
    for port, extra in [(17779, []), (17780, ['--replicaof', '127.0.0.1', '17779'])]:
        p = subprocess.Popen(['./src/valkey-server', '--port', str(port), '--bind', '127.0.0.1', '--save', '', '--appendonly', 'no', '--aclfile', '/dev/null', '--repl-diskless-sync-delay', '0'] + extra, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        servers.append(p)
        for _ in range(100):
            r = subprocess.run(['./src/valkey-cli', '-p', str(port), 'ping'], capture_output=True, text=True)
            if r.stdout.strip() == 'PONG': break
            if p.poll() is not None: raise RuntimeError(p.stdout.read())
            time.sleep(.05)
        else: raise RuntimeError('server did not start')
    for _ in range(200):
        r = subprocess.run(['./src/valkey-cli', '-p', '17780', 'info', 'replication'], capture_output=True, text=True)
        if 'master_link_status:up' in r.stdout: break
        time.sleep(.05)
    else: raise RuntimeError('replication did not connect')
    r = subprocess.run(['./src/valkey-cli', '-p', '17780', 'acl', 'load'], capture_output=True, text=True)
    print('ACL LOAD:', r.returncode, repr(r.stdout), repr(r.stderr))
    try: print('replica exit:', servers[1].wait(timeout=5))
    except subprocess.TimeoutExpired: print('replica still running')
finally:
    for p in servers:
        if p.poll() is None: p.terminate()
        output, _ = p.communicate(timeout=10)
        print(output[-16000:])
PY

cd /testbed && python3 - <<'PY'
import json, subprocess, time
primary = subprocess.Popen(['./src/valkey-server', '--port', '17779', '--bind', '127.0.0.1', '--save', '', '--appendonly', 'no', '--repl-diskless-sync-delay', '0'], stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT)
def cli(port, *args):
    return subprocess.run(['./src/valkey-cli', '-p', str(port), *args], capture_output=True, text=True, timeout=10)
try:
    for _ in range(100):
        if cli(17779, 'ping').stdout.strip() == 'PONG': break
        time.sleep(.05)
    else: raise RuntimeError('primary did not start')
    cmd = ['peeky', 'probe', '.', '--binary', 'src/valkey-server', '--at', 'src/acl.c:2382', '--capture', 'c,c.user,c.flag.master,original,channels', '--until', 'hits', '--timeout', '60', '--background', '--', '--port', '17780', '--bind', '127.0.0.1', '--save', '', '--appendonly', 'no', '--aclfile', '/dev/null', '--replicaof', '127.0.0.1', '17779']
    print('COMMAND:', ' '.join(cmd), flush=True)
    launch = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
    print(launch.stdout, launch.stderr, flush=True)
    if launch.returncode: raise RuntimeError('Peeky launch refused')
    job = json.loads(launch.stdout)['job']
    for _ in range(400):
        if 'master_link_status:up' in cli(17780, 'info', 'replication').stdout: break
        time.sleep(.05)
    else: raise RuntimeError('debugged replica did not connect')
    r = cli(17780, 'acl', 'load')
    print('ACL LOAD:', r.returncode, repr(r.stdout), repr(r.stderr), flush=True)
    result = subprocess.run(['peeky', 'job', 'wait', job, '--timeout', '30'], capture_output=True, text=True, timeout=40)
    print(result.stdout, result.stderr, flush=True)
finally:
    if primary.poll() is None: primary.terminate()
    primary.wait(timeout=10)
PY

