patch -p0 <<'PATCH'
--- tests/unit/acl.tcl
+++ tests/unit/acl.tcl
@@ -1,3 +1,38 @@
+set replica_acl_path [tmpdir "replica.acl"]
+exec cp -f tests/assets/user.acl $replica_acl_path
+start_server {tags {acl external:skip} overrides {repl-diskless-sync-delay 0}} {
+    start_server [list overrides [list dir $replica_acl_path aclfile user.acl] tags {acl external:skip}] {
+        test {ACL LOAD on a replica preserves the replication link} {
+            set primary [srv -1 client]
+            set replica [srv 0 client]
+            $replica replicaof [srv -1 host] [srv -1 port]
+            wait_for_sync $replica
+
+            $primary set acl-load-key before
+            assert_equal 1 [$primary wait 1 5000]
+            assert_equal before [$replica get acl-load-key]
+
+            $replica ACL SETUSER default -set
+            $replica ACL SAVE
+            $replica ACL SETUSER alice -get
+            set user_client [valkey_client]
+            $user_client AUTH alice alice
+            assert_error {NOPERM*} {$user_client get acl-load-key}
+
+            assert_equal OK [$replica ACL LOAD]
+            assert_equal before [$user_client get acl-load-key]
+            assert_error {NOPERM*} {$replica set acl-load-key forbidden}
+
+            $primary set acl-load-key after
+            assert_equal 1 [$primary wait 1 5000]
+            assert_equal after [$user_client get acl-load-key]
+            assert_equal up [status $replica master_link_status]
+            $user_client close
+        }
+    }
+}
+
 start_server {tags {"acl external:skip"}} {
     test {Connections start with the default user} {
         r ACL WHOAMI
PATCH
./runtest --single unit/acl --only 'ACL LOAD on a replica preserves the replication link'

